<script setup lang="ts">
import { computed, ref } from 'vue'
import { Coins, Plus, ArrowUpRight, ArrowDownRight, RefreshCcw, Building2, TrendingUp, ShieldCheck } from '@lucide/vue'
import UiModal from '../components/UiModal.vue'
import { useAppStore } from '../stores/app'

const store = useAppStore()
const showAllocate = ref(false)
const selectedDepartment = ref(store.departments[0]?.id ?? '')
const amount = ref(100)
const totalAllocated = computed(() => store.departments.reduce((sum, item) => sum + item.monthlyAllocation, 0))
const totalUsed = computed(() => store.departments.reduce((sum, item) => sum + item.used, 0))
const totalBalance = computed(() => store.departments.reduce((sum, item) => sum + item.balance, 0))
const logs = computed(() => store.transactions.slice().sort((a, b) => b.createdAt.localeCompare(a.createdAt)))
const departmentMap = computed(() => Object.fromEntries(store.departments.map((item) => [item.id, item.name])))
async function allocate() { await store.allocateTokens(selectedDepartment.value, amount.value); showAllocate.value = false }
</script>

<template>
  <div class="space-y-6">
    <section class="grid gap-4 md:grid-cols-3"><article class="card p-6"><div class="flex items-center justify-between"><span class="grid size-10 place-items-center rounded-xl bg-[#e6efe9] text-forest"><Coins :size="19" /></span><span class="badge bg-emerald-50 text-emerald-700">10월</span></div><p class="mt-6 text-3xl font-semibold tracking-[-.05em]">{{ totalAllocated.toLocaleString() }}<small class="ml-1 text-sm text-black/35">T</small></p><p class="mt-1 text-xs text-black/45">이번 달 총 배분</p></article><article class="card p-6"><div class="flex items-center justify-between"><span class="grid size-10 place-items-center rounded-xl bg-[#fbefe5] text-clay"><TrendingUp :size="19" /></span><span class="badge bg-orange-50 text-orange-700">{{ Math.round(totalUsed / totalAllocated * 100) }}%</span></div><p class="mt-6 text-3xl font-semibold tracking-[-.05em]">{{ totalUsed.toLocaleString() }}<small class="ml-1 text-sm text-black/35">T</small></p><p class="mt-1 text-xs text-black/45">누적 사용</p></article><article class="card p-6"><div class="flex items-center justify-between"><span class="grid size-10 place-items-center rounded-xl bg-[#e9edf5] text-[#526e9e]"><ShieldCheck :size="19" /></span><button class="btn-primary !px-3 !py-2" @click="showAllocate = true"><Plus :size="15" /> 추가 배분</button></div><p class="mt-6 text-3xl font-semibold tracking-[-.05em]">{{ totalBalance.toLocaleString() }}<small class="ml-1 text-sm text-black/35">T</small></p><p class="mt-1 text-xs text-black/45">전체 잔여 토큰</p></article></section>

    <section class="card p-6 sm:p-7"><div class="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p class="label">DEPARTMENT WALLETS</p><h2 class="mt-2 text-xl font-semibold tracking-[-.03em]">부서별 토큰 현황</h2></div><p class="text-[11px] text-black/40">매월 1일 자동 배분 · 미사용분 이월 정책 적용</p></div><div class="mt-7 grid gap-4 md:grid-cols-2 xl:grid-cols-4"><article v-for="dept in store.departments" :key="dept.id" class="rounded-2xl border border-black/7 p-5"><div class="flex items-center justify-between"><span class="grid size-9 place-items-center rounded-xl" :style="{ background: `${dept.color}18`, color: dept.color }"><Building2 :size="17" /></span><span class="text-[10px] font-semibold text-black/35">{{ Math.round(dept.used / dept.monthlyAllocation * 100) }}% 사용</span></div><b class="mt-5 block text-sm">{{ dept.name }}</b><p class="mt-2 text-2xl font-semibold tracking-[-.04em]">{{ dept.balance.toLocaleString() }}<small class="ml-1 text-xs text-black/35">T 잔여</small></p><div class="mt-4 h-1.5 overflow-hidden rounded-full bg-black/5"><div class="h-full rounded-full" :style="{ width: `${dept.used / dept.monthlyAllocation * 100}%`, background: dept.color }"></div></div><div class="mt-2 flex justify-between text-[10px] text-black/35"><span>사용 {{ dept.used.toLocaleString() }}</span><span>배분 {{ dept.monthlyAllocation.toLocaleString() }}</span></div></article></div></section>

    <section class="grid gap-6 xl:grid-cols-[1.35fr_1fr]"><article class="card p-6"><div><p class="label">TOKEN LEDGER</p><h3 class="mt-2 text-lg font-semibold">최근 거래 내역</h3></div><div v-if="logs.length" class="mt-5 divide-y divide-black/6"><div v-for="tx in logs" :key="tx.id" class="flex items-center justify-between gap-4 py-4"><div class="flex min-w-0 items-center gap-3"><span :class="['grid size-9 shrink-0 place-items-center rounded-xl', tx.amount > 0 ? 'bg-emerald-50 text-emerald-700' : 'bg-orange-50 text-clay']"><ArrowDownRight v-if="tx.amount > 0" :size="17" /><ArrowUpRight v-else :size="17" /></span><div class="min-w-0"><b class="block truncate text-xs">{{ tx.description }}</b><p class="mt-1 text-[10px] text-black/40">{{ departmentMap[tx.departmentId] }} · {{ new Date(tx.createdAt).toLocaleString('ko-KR') }}</p></div></div><b :class="['shrink-0 text-sm', tx.amount > 0 ? 'text-emerald-700' : 'text-clay']">{{ tx.amount > 0 ? '+' : '' }}{{ tx.amount }}T</b></div></div><div v-else class="mt-6 rounded-2xl bg-[#f5f5f1] p-8 text-center"><RefreshCcw :size="22" class="mx-auto text-black/25" /><p class="mt-3 text-xs text-black/40">신규 예약 또는 토큰 배분 시 거래가 기록됩니다.</p></div></article><article class="card !bg-[#102f24] p-6 !text-white"><p class="text-[10px] font-bold tracking-[.18em] text-white/40">POLICY ENGINE</p><h3 class="mt-2 text-lg font-semibold">차등 요금 정책</h3><div class="mt-6 space-y-3"><div class="rounded-2xl bg-white/[.06] p-4"><div class="flex justify-between text-xs"><b>피크타임</b><span class="text-[#bad3c4]">× 1.5</span></div><p class="mt-1.5 text-[10px] text-white/40">평일 10:00–16:00 · 대형 회의실</p></div><div class="rounded-2xl bg-white/[.06] p-4"><div class="flex justify-between text-xs"><b>노쇼 패널티</b><span class="text-[#f0bc88]">+ 50%</span></div><p class="mt-1.5 text-[10px] text-white/40">입실 미확인 3회 이상</p></div><div class="rounded-2xl bg-white/[.06] p-4"><div class="flex justify-between text-xs"><b>친환경 인센티브</b><span class="text-[#bad3c4]">− 2T</span></div><p class="mt-1.5 text-[10px] text-white/40">전기 업무차량 선택 시</p></div></div><p class="mt-5 text-[10px] leading-relaxed text-white/35">정책은 관리자 승인 후 다음 정산 주기부터 적용됩니다.</p></article></section>

    <UiModal v-if="showAllocate" title="토큰 추가 배분" description="즉시 부서 지갑에 반영되며 원장에 기록됩니다." @close="showAllocate = false"><form class="space-y-5" @submit.prevent="allocate"><label class="block"><span class="label mb-2 block">배분 부서</span><select v-model="selectedDepartment" class="field"><option v-for="dept in store.departments" :key="dept.id" :value="dept.id">{{ dept.name }} · 잔여 {{ dept.balance.toLocaleString() }}T</option></select></label><label class="block"><span class="label mb-2 block">배분 수량</span><input v-model.number="amount" type="number" min="1" step="10" class="field" /></label><div class="grid grid-cols-3 gap-2"><button v-for="preset in [100, 300, 500]" :key="preset" type="button" class="rounded-xl bg-black/[.04] py-2 text-xs font-semibold hover:bg-black/[.07]" @click="amount = preset">+{{ preset }}T</button></div><button class="btn-primary w-full"><Plus :size="16" /> {{ amount.toLocaleString() }} 토큰 배분</button></form></UiModal>
  </div>
</template>

